CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cards(card_id TEXT PRIMARY KEY CHECK(length(card_id)>0), konami_id INTEGER NOT NULL UNIQUE CHECK(konami_id>0), name TEXT NOT NULL CHECK(length(name)>0), source TEXT, acquired_at TEXT, verification TEXT NOT NULL DEFAULT 'UNVERIFIED_SOURCE' CHECK(verification IN ('UNVERIFIED_SOURCE','GAME_VERIFIED')));
CREATE TABLE card_attributes(card_id TEXT PRIMARY KEY REFERENCES cards(card_id), kind TEXT, attribute TEXT, race TEXT, level INTEGER, rank INTEGER, link INTEGER, atk INTEGER, def INTEGER, source TEXT, acquired_at TEXT, verification TEXT NOT NULL DEFAULT 'UNVERIFIED_SOURCE');
CREATE TABLE md_catalog(card_id TEXT PRIMARY KEY REFERENCES cards(card_id), rarity TEXT CHECK(rarity IS NULL OR rarity IN ('N','R','SR','UR')), rarity_source TEXT CHECK(rarity IS NULL OR (rarity_source IS NOT NULL AND rarity_source LIKE 'MD:%')), craftable TEXT NOT NULL DEFAULT 'UNKNOWN' CHECK(craftable IN ('YES','NO','UNKNOWN')), source TEXT, acquired_at TEXT, verification TEXT NOT NULL DEFAULT 'UNVERIFIED_SOURCE');
CREATE TABLE card_texts(card_id TEXT NOT NULL REFERENCES cards(card_id), language TEXT NOT NULL, version TEXT NOT NULL, body TEXT NOT NULL, source TEXT, acquired_at TEXT, verification TEXT NOT NULL DEFAULT 'UNVERIFIED_SOURCE', PRIMARY KEY(card_id,language,version));
CREATE TABLE banlist_snapshots(snapshot_id TEXT PRIMARY KEY, format_id TEXT NOT NULL, effective_on TEXT NOT NULL, source TEXT, acquired_at TEXT, verification TEXT NOT NULL DEFAULT 'UNVERIFIED_SOURCE' CHECK(verification IN ('UNVERIFIED_SOURCE','GAME_VERIFIED')));
CREATE TABLE banlist_entries(snapshot_id TEXT NOT NULL REFERENCES banlist_snapshots(snapshot_id), card_id TEXT NOT NULL REFERENCES cards(card_id), max_copies INTEGER NOT NULL CHECK(max_copies IN (0,1,2,3)), PRIMARY KEY(snapshot_id,card_id));
CREATE TABLE inventory_batches(batch_id TEXT PRIMARY KEY, payload TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, undo_of TEXT UNIQUE REFERENCES inventory_batches(batch_id));
CREATE TABLE inventory(card_id TEXT PRIMARY KEY REFERENCES cards(card_id), owned_count INTEGER, known_state TEXT NOT NULL CHECK((known_state='UNKNOWN' AND owned_count IS NULL) OR (known_state='KNOWN_ZERO' AND owned_count=0) OR (known_state='KNOWN_POSITIVE' AND typeof(owned_count)='integer' AND owned_count>0)), updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_batch_id TEXT REFERENCES inventory_batches(batch_id));
CREATE TABLE inventory_history(id INTEGER PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES inventory_batches(batch_id), card_id TEXT NOT NULL REFERENCES cards(card_id), before_count INTEGER, before_state TEXT NOT NULL, after_count INTEGER, after_state TEXT NOT NULL, changed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(batch_id,card_id));
CREATE TABLE decks(deck_id TEXT PRIMARY KEY, name TEXT NOT NULL, format_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, notes TEXT);
CREATE TABLE deck_cards(deck_id TEXT NOT NULL REFERENCES decks(deck_id), card_id TEXT NOT NULL REFERENCES cards(card_id), section TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), PRIMARY KEY(deck_id,card_id,section));
INSERT INTO schema_migrations(version) VALUES (1);
